-- Subject set: the flight lead's missions, assignedSquadron IN subject.squadrons OR bookedBy = subject, under bare-column tenancy.
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedBy, AssignedSquadronId, StatusId, Notes FROM Missions WHERE (`Missions`.`SectorId` = 'anvil') AND (EXISTS (SELECT 1 FROM `SquadronMemberships` `ca1` WHERE `ca1`.`UserId` = 'lead' AND `ca1`.`SquadronId` = `Missions`.`AssignedSquadronId` AND EXISTS (SELECT 1 FROM `Squadrons` `ca2` WHERE `ca2`.`Id` = `ca1`.`SquadronId` AND EXISTS (SELECT 1 FROM `Wings` `ca3` WHERE `ca3`.`Id` = `ca2`.`WingId` AND `ca3`.`SectorId` = 'anvil'))) OR `Missions`.`BookedBy` = 'lead') ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
